function lessonDatesForClass(c,paidAt,count=termLessons(c)){
  if(!c||!paidAt||!classDays(c).length||!/^([01]\d|2[0-3]):[0-5]\d$/.test(c.time||''))return [];
  const paidMs=Date.parse(/^\d{4}-\d{2}-\d{2}$/.test(paidAt)?`${paidAt}T00:00:00+08:00`:paidAt);
  if(!Number.isFinite(paidMs))return [];
  const paidDay=new Date(paidMs+8*3600000).toISOString().slice(0,10);
  const day=new Date(`${paidDay}T00:00:00Z`),dates=[];
  for(let offset=0;offset<count*7+7&&dates.length<count;offset++){
    const key=day.toISOString().slice(0,10);
    if(classOccursOn(c,key,true)&&Date.parse(`${key}T${c.time}:00+08:00`)>paidMs)dates.push(key);
    day.setUTCDate(day.getUTCDate()+1);
  }
  return dates;
}
