function portalIcon(id){let paths={sales:'M4 8h16v12H4z M7 8V4h10v4 M7 12h2m3 0h2m3 0h1 M7 16h10',timetable:'M4 5h16v15H4z M8 3v4m8-4v4M4 10h16 M8 13h1m3 0h1m3 0h1M8 16h1m3 0h1',courses:'M3 5l9 2 9-2v14l-9 2-9-2z M12 7v14',fees:'M12 3v18 M16 7c-1-3-9-3-9 1s10 3 10 7-8 4-10 1',products:'M4 8h16v12H4z M3 4h18v4H3z M9 12h6',messages:'M3 4h15v11H8l-5 4z M18 8h3v13l-5-4h-5',students:'M2 8l10-5 10 5-10 5z M6 10v7l6 3 6-3v-7 M22 8v9',leads:'M3 4h18l-7 8v7l-4 2v-9z',accounting:'M5 3h14v18H5z M8 7h8 M8 11h2m4 0h2M8 15h2m4 0h2 M8 18h2m4 0h2',reports:'M5 20V10m7 10V4m7 16v-7',staffs:'M8 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21v-3a6 6 0 0 1 12 0v3 M17 4a4 4 0 0 1 0 8m0 3a5 5 0 0 1 5 5',channels:'M3 3h4v4H3z M10 3h4v4h-4z M17 3h4v4h-4z M3 10h4v4H3z M10 10h4v4h-4z M17 10h4v4h-4z M3 17h4v4H3z M10 17h4v4h-4z M17 17h4v4h-4z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M10 3h4l1 3 3 1 3 3v4l-3 1-1 3-3 3h-4l-1-3-3-1-3-3v-4l3-1 1-3z',menu:'M3 6h18M3 12h18M3 18h18',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(paths[id]||paths.courses).split(' M').map((d,i)=>`<path d="${i?'M':''}${d}"/>`).join('')}</svg>`}
// Keep the existing page mounted so the sidebar transition preserves drafts and focus.
function syncPortalMenu(){
  if(!isAccountPage())return;
  let shell=document.querySelector('.portal-shell'),sidebar=document.querySelector('#portal-sidebar'),button=document.querySelector('[data-action="portal-menu"]');
  if(!shell||!sidebar||!button)return;
  let mobile=portalViewport?.matches||false;
  shell.classList.toggle('is-menu-open',portalMenu);
  sidebar.inert=mobile&&!portalMenu;
  button.setAttribute('aria-expanded',String(mobile?portalMenu:!portalMenu));
}
