function isScopedTeacher(){return sharedMode&&authUser?.role==='teacher'}
function portalItems(){if(isScopedTeacher())return [['overview','timetable','時間表','Timetable'],['catalog','courses','課程','Courses'],['fees','fees','費用','Fees']];if(role==='student')return [['overview','timetable','我的時間表','My Calendar'],['courses','courses','我的課程','My classes'],['payments','fees','付款及個人資料','Payments & profile']];let teacher=role==='teacher';return [[teacher?'new-enrolments':'sales','sales','銷售','Sales'],['overview','timetable','時間表','Timetable'],['catalog','courses','課程','Courses'],[teacher?'fees':'payments','fees','費用','Fees'],['products','products','產品','Products'],['messages','messages','訊息','Messages'],[teacher?'student-list':'student-placeholder','students','學生','Students'],['leads','leads','潛在客戶','Leads'],['accounting','accounting','會計','Accounting'],['reports','reports','報告','Reports'],[teacher?'management':'staff-placeholder','staffs','員工','Staffs'],['channels','channels','渠道','Channels'],['settings','settings','設定','Settings']]}
