 let record={id:current?.id||(sharedMode?'':'course-'+db.next++),courseName,feeName,category:String(data.category||'').trim().slice(0,200),level:String(data.level||'').trim().slice(0,200),pricingModel:model,price,...(model==='package'?{packageType:data.packageType,packageTotal}:{months,...(model==='monthly-lessons'?{duration}:{})}),bookingExpiry:data.expiryEnabled?{value:Number(data.expiryValue),unit:data.expiryUnit}:null,onlineStore:!!data.onlineStore};
