function sharedErrorText(error){
 if(error.code==='IDEMPOTENCY_CONFLICT')return t('此儲存要求已被處理，請重新整理清單，核對資料後再修改。','This save request has already been handled. Refresh the list, review the record, then edit it.');
 if(error.code==='COURSE_HAS_SCHEDULES')return t('此課程仍有時間安排。請先到時間表處理相關排課，再刪除課程；現有課堂未有改動。','This course still has schedules. Handle them in the timetable before deleting the course; existing lessons are unchanged.');
 if(error.code==='COURSE_DELETED')return t('此課程已刪除。請先還原課程，再修改或新增相關資料。','This course is deleted. Restore it before editing or adding related records.');
 if(error.code==='COURSE_NAME_DELETED')return t('此名稱屬於已刪除的課程。請到「已刪除」清單還原原有課程。','This name belongs to a deleted course. Restore the original course from the Deleted list.');
 if(error.code==='COURSE_NAME_EXISTS')return t('此課程名稱已被使用。如要加入另一項費用，請在該課程的費用區按新增。','This course name already exists. To add another fee, use Add in that course’s Fees section.');
 if(error.status===409)return t('資料已被另一位使用者修改。請關閉表單並重新開啟，核對最新內容後再儲存。','Another user changed this record. Close and reopen the form, review the latest values, then save again.');
 if(error.status===401)return t('登入資料不正確或登入已過期，請重新登入。','Incorrect credentials or your session has expired. Please log in again.');
 if(error.status===403)return t('此帳戶未獲准進行這個操作。','This account is not permitted to perform this action.');
 if(error.status===429)return t('登入嘗試過多，請稍後再試。','Too many login attempts. Please try again shortly.');
 if(!error.status||error.code==='service_unavailable')return t('暫時未能連接系統，請稍後重試。已填寫的內容會保留。','Could not connect. Please retry shortly; your entered values are retained.');
 return t('未能儲存，請核對欄位內容及金額（最多兩位小數）後重試。','Could not save. Check the fields and the amount (at most two decimal places), then retry.');
}
