 const generation=sharedGeneration;
 const read=async()=>{let records,fees;if(typeof sharedClient.catalog==='function'){let catalog=await sharedClient.catalog(sharedCatalogRevision);if(generation!==sharedGeneration)return;if(catalog.unchanged){paintSharedUpdates(paint);return}records=hydrateCatalogCourses(catalog);fees=catalog.fees;sharedCatalogRevision=catalog.revision;}else{let [data,feeData]=await Promise.all([sharedClient.courses(),authUser.role==='student'?Promise.resolve({fees:[]}):sharedClient.fees()]);if(generation!==sharedGeneration)return;records=data.courses;fees=feeData.fees;}let changed=JSON.stringify(records)!==JSON.stringify(db.courseSettings)||JSON.stringify(fees)!==JSON.stringify(sharedFees);sharedFees=fees;applySharedCourses(records);sharedViewDirty=sharedViewDirty||changed;paintSharedUpdates(paint);};
