async function saveSchedulingResource(data,form){
 if(!canEditSchedules()||!resourceManager||!resourceDraft||resourceSaving||!form)return;
 const draft=resourceDraft,record={kind:draft.kind,displayName:String(data.displayName||'').trim(),active:!!data.active};
 if(draft.kind==='room')Object.assign(record,{capacity:String(data.capacity??'').trim()===''?null:Number(data.capacity),detail:String(data.detail||'').trim(),remark:String(data.remark||'').trim(),externalLocation:!!data.externalLocation});
 const errorNode=document.querySelector('#resource-editor-error');
 if(!record.displayName||record.displayName.length>200||draft.kind==='room'&&(record.capacity!==null&&(!Number.isSafeInteger(record.capacity)||record.capacity<1)||record.detail.length>2000||record.remark.length>2000)){errorNode.textContent=t('請檢查名稱及課室資料，容量須為正整數或留空。','Check the name and room details. Capacity must be a positive whole number or blank.');return;}
 const generation=resourceGeneration,job={};resourceSaving=true;resourceJob=job;const controls=[...document.querySelectorAll('.resource-editor-dialog button,.resource-editor-dialog input,.resource-editor-dialog textarea')],previous=new Map(controls.map(c=>[c,!!c.disabled]));controls.forEach(c=>c.disabled=true);form.setAttribute('aria-busy','true');errorNode.textContent='';
 const button=document.querySelector('#resource-editor-save'),label=button?.textContent;if(button)button.textContent=t('儲存中…','Saving…');
 try{
  const {resource}=await sharedClient.saveSchedulingResource(record,draft.current,draft.key);if(resourceGeneration!==generation||resourceJob!==job)return;
  if(!resource?.id)throw new Error('Invalid resource acknowledgement');resourceGeneration++;resourceRevision='';const index=sharedSchedulingResources.findIndex(r=>r.id===resource.id);if(index<0)sharedSchedulingResources.push(resource);else if(sharedSchedulingResources[index].version<=resource.version)sharedSchedulingResources[index]=resource;
  resourceReady=true;resourceDraft=null;resourceManager.kind=draft.kind;resourceManager.query='';resourceManager.status=resource.active?'active':'inactive';sharedViewDirty=true;drawSchedulingResources(`[data-resource-id="${resource.id}"]`);toast(t('排課資料已儲存','Scheduling resource saved'));
 }catch(error){if(generation!==resourceGeneration||resourceJob!==job||error.code==='AUTH_SUPERSEDED')return;if(error.status===401){applySharedUser(null);go('/login');return;}if(errorNode.isConnected!==false)errorNode.textContent=resourceErrorText(error);}
 finally{if(resourceJob===job){resourceSaving=false;resourceJob=null;form.removeAttribute('aria-busy');for(const [control,disabled]of previous)control.disabled=disabled;if(button)button.textContent=label;}}
}
function schedulingResourceKeyboard(e){
 if(!resourceManager)return false;if(e.key==='Escape'){e.preventDefault();if(!resourceSaving){if(resourceDraft)cancelSchedulingResourceEditor();else closeSchedulingResources();}return true;}
 if(e.key==='Tab'){const selector=resourceDraft?'.resource-editor-dialog':'.resource-manager-dialog',controls=[...document.querySelectorAll(`${selector} button:not(:disabled),${selector} input:not(:disabled),${selector} select:not(:disabled),${selector} textarea:not(:disabled)`)],first=controls[0],last=controls.at(-1);if(!controls.length||e.shiftKey&&document.activeElement===first||!e.shiftKey&&document.activeElement===last){e.preventDefault();(e.shiftKey?last:first)?.focus();}}return true;
}
