 if(action==='resource-open'){openSchedulingResources();return;}if(!resourceManager||resourceSaving)return;
 if(action==='resource-close')closeSchedulingResources();else if(action==='resource-editor-cancel')cancelSchedulingResourceEditor();else if(action==='resource-add')openSchedulingResourceEditor();else if(action==='resource-edit')openSchedulingResourceEditor(d.resourceId);else if(action==='resource-refresh')refreshSharedResources();else if(action==='resource-set-kind'&&['teacher','room'].includes(d.resourceKind)&&!resourceDraft){resourceManager.kind=d.resourceKind;resourceManager.query='';drawSchedulingResources(`[data-resource-kind="${d.resourceKind}"]`);}
