function teacherAccessButton(){return sharedMode&&authUser?.role==='admin'?`<button class="ghost access-open" data-action="access-open">${t('老師資料權限','Teacher access')}</button>`:'';}
function teacherAccessErrorText(error){if(error.code==='GRANT_EXISTS')return t('這個查看授權已存在；請在清單中啟用或撤銷。','This read grant already exists. Enable or revoke it in the list.');if(error.status===409)return t('資料已被其他管理員更新。已填內容保留；請取消後重新開啟最新資料。','Another administrator updated this record. Your input is retained; cancel and reopen the latest record.');if(error.status===400)return t('請選擇有效的帳戶與授權對象。','Choose a valid account and target.');return sharedErrorText(error);}
function teacherAccessOccurrences(){const from=timetableDate,selected=timetableDateObject(from),end=new Date(selected);end.setDate(end.getDate()+365);const to=end.getFullYear()>9999?'9999-12-31':timetableDateKey(end),rows=db.schedules.flatMap(series=>scheduleOccurrences(series,from,to));for(const grant of teacherAccessCache.grants)if(grant.kind==='occurrence'){const series=db.schedules.find(row=>row.id===grant.scheduleId),occurrence=series&&scheduleOccurrence(series,grant.sequence);if(occurrence&&!rows.some(row=>row.item.id===occurrence.item.id&&row.sequence===occurrence.sequence))rows.push(occurrence);}return rows.sort((a,b)=>a.date.localeCompare(b.date)||a.item.time.localeCompare(b.item.time)||a.item.id.localeCompare(b.item.id));}
function drawTeacherAccess(focus='[data-action="access-close"]'){
 if(!teacherAccessManager)return;const manager=teacherAccessManager;manager.viewRevision=teacherAccessCache.revision;manager.viewReady=teacherAccessReady;manager.viewError=teacherAccessError;manager.viewResources=resourceRevision;manager.viewCatalog=sharedCatalogRevision;manager.viewSchedules=sharedSchedulesRevision;
 modal=accessControlMarkup({...teacherAccessCache,resources:sharedSchedulingResources,courses:db.courseSettings,occurrences:teacherAccessOccurrences(),selectedUserId:manager.selectedUserId,tab:manager.tab,busy:teacherAccessSaving||!teacherAccessReady&&!teacherAccessError,error:teacherAccessError},{t,esc});renderModal();const target=focus&&document.querySelector(focus);if(target&&!target.disabled)target.focus();else document.querySelector('.access-dialog')?.focus();
}
async function refreshTeacherAccess({paint=true}={}){
 if(!sharedMode||authUser?.role!=='admin'||typeof sharedClient.accessControl!=='function')return;if(teacherAccessRead)return teacherAccessRead;
 const generation=teacherAccessGeneration,pending=(async()=>{try{const data=await sharedClient.accessControl(teacherAccessCache.revision);if(generation!==teacherAccessGeneration)return;if(!data.unchanged){if(!Array.isArray(data.accounts)||!Array.isArray(data.teacherLinks)||!Array.isArray(data.grants))throw new Error('Invalid access-control response');teacherAccessCache={accounts:data.accounts,teacherLinks:data.teacherLinks,grants:data.grants,revision:data.revision||''};}teacherAccessReady=true;teacherAccessError='';if(teacherAccessManager&&!teacherAccessManager.selectedUserId)teacherAccessManager.selectedUserId=teacherAccessCache.accounts.find(account=>account.role==='teacher')?.id||'';}catch(error){if(generation!==teacherAccessGeneration||error.code==='AUTH_SUPERSEDED')return;if(error.status===401){applySharedUser(null);go('/login');return;}teacherAccessError=teacherAccessErrorText(error);}if(generation!==teacherAccessGeneration)return;if(paint&&teacherAccessManager&&!teacherAccessDraft&&!document.activeElement?.matches?.('input,select,textarea')&&(teacherAccessManager.viewRevision!==teacherAccessCache.revision||teacherAccessManager.viewReady!==teacherAccessReady||teacherAccessManager.viewError!==teacherAccessError||teacherAccessManager.viewResources!==resourceRevision||teacherAccessManager.viewCatalog!==sharedCatalogRevision||teacherAccessManager.viewSchedules!==sharedSchedulesRevision))drawTeacherAccess();})();teacherAccessRead=pending;try{await pending}finally{if(teacherAccessRead===pending)teacherAccessRead=null;}
}
