function closeTeacherAccess(){if(!teacherAccessManager||teacherAccessSaving)return;const opener=teacherAccessManager.opener;teacherAccessManager=null;teacherAccessDraft=null;modal='';renderModal();if(opener?.isConnected!==false)opener?.focus();else document.querySelector('[data-action="access-open"]')?.focus();}
