function openTeacherLinkEditor(resourceId){if(!teacherAccessManager||teacherAccessSaving||authUser?.role!=='admin')return;const resource=sharedSchedulingResources.find(row=>row.id===resourceId&&row.kind==='teacher');if(!resource)return;const current=teacherAccessCache.teacherLinks.find(row=>row.teacherResourceId===resourceId);teacherAccessDraft={kind:'link',resourceId,current:current?{...current}:null,key:newOperationKey()};modal=accessTeacherLinkEditorMarkup({resource,accounts:teacherAccessCache.accounts,current},{t,esc});renderModal();document.querySelector('#access-link-user')?.focus();}
