function handleTeacherAccessAction(action,data={}){if(action==='access-open'){openTeacherAccess();return;}if(!teacherAccessManager||teacherAccessSaving)return;if(action==='access-close')closeTeacherAccess();else if(action==='access-editor-cancel')cancelTeacherAccessEditor();else if(action==='access-link-edit')openTeacherLinkEditor(data.resourceId);else if(action==='access-grant-add')openTeacherGrantEditor();else if(action==='access-grant-toggle')toggleTeacherGrant(data.grantId);else if(action==='access-tab'&&['links','grants'].includes(data.accessTab)){teacherAccessManager.tab=data.accessTab;drawTeacherAccess(`[data-access-tab="${data.accessTab}"]`);}else if(action==='access-refresh')refreshTeacherAccess();}
function teacherAccessKeyboard(event){if(!teacherAccessManager)return false;if(event.key==='Escape'){event.preventDefault();if(!teacherAccessSaving){if(teacherAccessDraft)cancelTeacherAccessEditor();else closeTeacherAccess();}return true;}if(event.key==='Tab'){const controls=[...document.querySelectorAll('.access-dialog button:not(:disabled),.access-dialog input:not(:disabled),.access-dialog select:not(:disabled),.access-dialog textarea:not(:disabled)')].filter(control=>!control.closest?.('[hidden],fieldset[disabled]')),first=controls[0],last=controls.at(-1);if(!controls.includes(document.activeElement)||event.shiftKey&&document.activeElement===first||!event.shiftKey&&document.activeElement===last){event.preventDefault();((event.shiftKey?last:first)||document.querySelector('.access-dialog'))?.focus();}}return true;}
function ensureSharedPolling(){if(!sharedMode||sharedPollingStarted)return;sharedPollingStarted=true;const refresh=async()=>{if(await refreshSharedSession())await Promise.all([refreshSharedCourses(),refreshActiveMaterials(),refreshSharedSchedules(),teacherAccessManager?refreshTeacherAccess():Promise.resolve()]);};window.setInterval(refresh,5000);window.addEventListener('focus',refresh);}
async function initialiseSharedService(){
 if(!sharedClient)return;
 let generation=sharedGeneration,discarded=false;
 try{let health=await sharedClient.health();if(generation!==sharedGeneration){discarded=true;return}if(health.mode!=='shared-test')throw new Error('Unexpected service');sharedMode=true;let session=await sharedClient.session();if(generation!==sharedGeneration){discarded=true;return}applySharedUser(session.user);generation=sharedGeneration;if(authUser){await refreshSharedCourses({paint:false});await refreshSharedSchedules({paint:false});}}
 catch(error){if(error.code==='AUTH_SUPERSEDED'||generation!==sharedGeneration)discarded=true;else{applySharedUser(null);generation=sharedGeneration;}}
 finally{sharedReady=true;if(!discarded&&generation===sharedGeneration){if(authUser&&path()==='/login')go('/account');else render();}ensureSharedPolling();}
}
async function sharedLogin(data,form){
 let button=form.querySelector('button[type=submit],button'),errorNode=document.querySelector('#login-error');if(loginPending)return;loginPending=true;if(button){button.disabled=true;button.textContent=t('登入中…','Signing in…');}errorNode.textContent='';
 let generation=sharedGeneration;
 try{let result=await sharedClient.login(String(data.username||'').trim(),String(data.password||''));if(generation!==sharedGeneration)return;sharedMode=true;ensureSharedPolling();applySharedUser(result.user);generation=sharedGeneration;await refreshSharedCourses({paint:false});await refreshSharedSchedules({paint:false});if(generation!==sharedGeneration)return;tab=role==='student'?'overview':'catalog';courseSearch='';portalMenu=false;go('/account');}
 catch(error){if(error.code==='AUTH_SUPERSEDED'||generation!==sharedGeneration)return;if(errorNode.isConnected!==false)errorNode.textContent=sharedErrorText(error);}
 finally{loginPending=false;if(button){button.disabled=false;button.textContent=t('登入','Login');}}
}
