 let generation=sharedGeneration;try{let result=await sharedClient.saveCourse(record,current,form.dataset.operationKey);if(generation!==sharedGeneration)return;applyCourseAcknowledgement(result.course);modal='';courseSearch='';tab='catalog';render();toast(t('課程已儲存','Course saved'));}
 catch(error){if(generation!==sharedGeneration)return;if(error.status===401){applySharedUser(null);go('/login');return}let errorNode=form.isConnected===false?null:document.querySelector('#create-course-error');if(errorNode)errorNode.textContent=sharedErrorText(error);if(error.status===409)await refreshSharedCourses({paint:false}).catch(()=>{});}
