let timetableViewSettings=loadTimetableViewSettings(),timetableSettingsDraft=null;
function timetableSettingsPreview(){let d=timetableSettingsDraft||timetableViewSettings,interval=Number(d.intervalDuration)||15,height=Number(d.intervalHeight)||30;return `<span>09:30</span><div class="tt-setting-measure"><span aria-hidden="true">↕</span><span>${height}px</span></div><span>${scheduleTime(570+interval)}</span>`}
function openTimetableViewSettings(){if(!['teacher','student'].includes(role))return;timetableSettingsDraft=normalizeTimetableViewSettings(timetableViewSettings);let d=timetableSettingsDraft,select=(name,label,options)=>scheduleField(label,`<select name="${name}">${options.map(([value,z,e])=>`<option value="${value}" ${d[name]===value?'selected':''}>${t(z,e)}</option>`).join('')}</select>`);modal=`<div class="modal tt-settings-modal" role="dialog" aria-modal="true" aria-labelledby="tt-settings-title"><div class="dialog tt-settings-dialog"><header><h2 id="tt-settings-title">${t('月曆檢視設定','Calendar View Settings')}</h2><button type="button" class="ghost" data-action="tt-close-settings" aria-label="${t('關閉月曆設定','Close calendar settings')}">×</button></header><form id="tt-view-settings"><section class="tt-settings-main"><div class="tt-settings-fields">${select('rangeDays',t('連續顯示日數','Consecutive days'),Array.from({length:14},(_,i)=>[i+1,`${i+1} 日`,`${i+1} ${i?'days':'day'}`]))}${select('calendarType',t('月曆類型','Calendar Type'),[['fixed','固定時間格','Fixed Intervals'],['compact','緊湊','Compact']])}${scheduleField(t('每格時間（分鐘）','Interval Duration (min)'),`<input name="intervalDuration" type="number" min="5" max="60" step="5" required value="${d.intervalDuration}" ${d.calendarType==='compact'?'disabled':''}>`)}${scheduleField(t('每格高度（像素）','Interval Height (px)'),`<input name="intervalHeight" type="number" min="20" max="120" step="1" required value="${d.intervalHeight}">`)}${select('studentsNumbering',t('學生排列標記','Students Numbering'),[['decimal','數字','Decimal'],['disc','圓點','Disc'],['none','無','None']])}</div><div id="tt-settings-preview" class="tt-settings-preview" aria-label="${t('時間格預覽','Interval preview')}">${timetableSettingsPreview()}</div></section><section class="tt-settings-elements"><h3>${t('課堂顯示資料','Calendar Record Elements')}</h3><div class="tt-settings-switches">${[timetableRecordElements.slice(0,8),timetableRecordElements.slice(8)].map(group=>`<div>${group.map(([key,z,e])=>`<label class="tt-settings-switch"><input type="checkbox" role="switch" name="${key}" ${d.elements[key]?'checked':''}><span class="tt-switch-track" aria-hidden="true"></span><span>${t(z,e)}</span></label>`).join('')}</div>`).join('')}</div></section><p id="tt-settings-error" class="error" role="alert"></p><footer><button type="submit">${t('確定','OK')}</button></footer></form></div></div>`;renderModal();document.querySelector('#tt-view-settings [name="calendarType"]')?.focus()}
function closeTimetableViewSettings(){if(!timetableSettingsDraft)return;timetableSettingsDraft=null;modal='';renderModal();document.querySelector('[data-action="tt-view-settings"]')?.focus()}
