function handleTimetableAction(action){if(role!=='teacher'&&!(role==='student'&&['tt-view-settings','tt-close-settings'].includes(action)))return;let date=timetableDateObject(timetableDate);switch(action){case 'tt-view-settings':openTimetableViewSettings();return;case 'tt-close-settings':closeTimetableViewSettings();return;case 'tt-add-schedule':openSchedule();return;case 'tt-schedule-preview':if(!scheduleDraft)return;schedulePreviewVisible=!schedulePreviewVisible;document.querySelector('#schedule-preview-content').innerHTML=schedulePreviewMarkup();document.querySelector('[data-action=tt-schedule-preview]').setAttribute('aria-expanded',schedulePreviewVisible);return;case 'tt-prev':case 'tt-next':if(timetableView==='range'){const range=timetableDateRange(timetableDate,timetableViewSettings.rangeDays);selectTimetableDate(action==='tt-prev'?range.previousStart:range.nextStart);render();return;}if(['month','list'].includes(timetableView)){let month=date.getMonth()+(action==='tt-prev'?-1:1);date=new Date(date.getFullYear(),month,Math.min(date.getDate(),new Date(date.getFullYear(),month+1,0).getDate()))}else date.setDate(date.getDate()+(action==='tt-prev'?-1:1)*(timetableView==='day'?1:7));selectTimetableDate(timetableDateKey(date));break;case 'tt-today':selectTimetableDate(localToday());break;case 'tt-month-prev':case 'tt-month-next':timetableMonth=new Date(timetableMonth.getFullYear(),timetableMonth.getMonth()+(action==='tt-month-prev'?-1:1),1);break;case 'tt-month-toggle':timetableMonthVisible=!timetableMonthVisible;break;case 'tt-filters':if(timetableView==='list')timetableListFiltersVisible=!timetableListFiltersVisible;else timetableFiltersVisible=!timetableFiltersVisible;break;case 'tt-clear-lesson':timetableLessonFilter=null;break;case 'tt-print':window.print?.();return;default:return}render()}

