 const form=document.querySelector('#schedule-editor'),controls=form?[...form.querySelectorAll('button,input,select,textarea'),document.querySelector('.schedule-dialog header button')].filter(Boolean):[],previous=new Map(controls.map(control=>[control,!!control.disabled]));controls.forEach(control=>control.disabled=true);
