function scheduleResourceOptions(kind){if(sharedMode)return sharedSchedulingResources.filter(r=>r.kind===kind&&r.active).map(r=>r.id);let stored=kind==='teacher'?previewTeachers.map(p=>p.name):[],values=[...stored,...db.classes.map(c=>c[kind]),...scheduleResourceRecords().map(s=>s?.[kind]),scheduleDraft?.[kind]];return [...new Set(values.filter(Boolean).map(String))].sort()}
