function scheduleFeeMarkup(){let d=scheduleDraft,settings=courseSettingsFor(d.course),fee=settings?.price??courses.find(c=>c.id===d.course)?.price;if(fee==null)return '';let label=settings?`${settings.feeName} · ${coursePriceDescription(settings)}`:t(`每期 ${termLessons(cl(d.id)||db.classes.find(c=>c.course===d.course))} 堂`,` ${termLessons(cl(d.id)||db.classes.find(c=>c.course===d.course))} lessons per term`);return `<div class="schedule-fee"><span>${esc(label)}</span><strong>${money(fee)}</strong></div>`}
