function portalReports(){return `<section class="portal-reports" aria-label="${t('報告清單','Reports list')}"><div class="report-groups">${reportGroups.map(group=>`<section class="report-group" aria-labelledby="report-group-${group.key}"><h2 id="report-group-${group.key}">${t(group.zh,group.en)}</h2><div class="report-list">${group.items.map(([zh,en,descriptionZh,descriptionEn],i)=>`<article class="report-entry"><h3><button type="button" disabled aria-describedby="report-${group.key}-${i}-description" title="${t('暫未啟用','Currently unavailable')}">${t(zh,en)}</button></h3><p id="report-${group.key}-${i}-description">${t(descriptionZh,descriptionEn)}</p></article>`).join('')}</div></section>`).join('')}</div></section>`}

function portalContent(){if(path()==='/account/fees')tab='fees';if(isScopedTeacher()&&(path().startsWith('/account/classes/')||!['overview','catalog','fees'].includes(tab)&&!path().startsWith('/account/courses/')))return `<section class="portal-content-padding"><h1>${t('老師可查看的資料','Authorized teacher data')}</h1><p>${t('此功能尚未接入老師資料權限。請使用時間表、課程及費用查看已獲授權的內容。','This feature is not yet connected to teacher permissions. Use Timetable, Courses and Fees to view your authorized data.')}</p><button data-tab="overview">${t('返回時間表','Back to timetable')}</button></section>`;if(role==='teacher'&&path().startsWith('/account/courses/'))return portalCourseDetail(accountCourseId());if(role==='student')return `<div class="portal-content-padding">${student()}</div>`;if(tab==='overview'&&!path().startsWith('/account/classes/'))return teacherTimetable();if(tab==='catalog')return portalCourses();if(tab==='fees')return portalFees();if(tab==='leads')return portalLeads();if(tab==='reports')return portalReports();if(tab==='settings')return `<div class="portal-page-heading"><h1>${t('設定','Settings')}</h1></div>${role==='teacher'?`<div class="portal-content-padding"><button data-tab="news">${t('消息管理','News management')}</button></div>`:''}`;if(['products','messages','accounting','channels','sales','student-placeholder','staff-placeholder'].includes(tab)){let item=portalItems().find(([id])=>id===tab);return `<section class="portal-blank-page"><div class="portal-page-heading"><h1>${item?t(item[2],item[3]):''}</h1></div></section>`}return `<div class="portal-content-padding">${role==='teacher'?teacher():student()}</div>`}
function account(){return `<div class="portal-shell ${portalMenu?'is-menu-open':''}"><nav id="portal-sidebar" class="portal-sidebar" aria-label="${t('帳戶導覽','Account navigation')}">${portalItems().map(([id,icon,z,e])=>`<button data-tab="${id}" class="${portalActiveTab()===id?'active':''}" ${portalActiveTab()===id?'aria-current="page"':''} aria-label="${t(z,e)}">${portalIcon(icon)}<span>${t(z,e)}</span></button>`).join('')}</nav><div class="portal-content">${portalContent()}</div></div>`}
