function joinDetailsError(data){let student=String(data.student??'').trim(),phone=String(data.phone??'').trim(),email=String(data.email??'').trim();if(!student||!email||!phone)return t('請填寫姓名、電話及電郵。','Please enter a name, phone number and email.');if(!/^[\p{L}\p{M} ]+$/u.test(student))return t('學生姓名只可包含文字及空格。','Student name may contain letters and spaces only.');if(!/^[0-9]+$/.test(phone))return t('電話只可包含數字。','Phone number may contain digits only.');return ''}
function markPaid(b){if(!b||b.status==='waitlist')return false;if(!b.paid){let paidAt=new Date().toISOString();let count=b.lessonCount||termLessons(cl(b.classId));if(lessonDatesForClass(cl(b.classId),paidAt,count).length!==count)return false;b.lessonCount=count;b.paid=true;b.paidAt=paidAt}b.status='confirmed';save();return true}
